import glob, os, fcsparser

for f in sorted(glob.glob("/task/input/fcs/*.fcs")):
    meta, _ = fcsparser.parse(f, reformat_meta=True)
    name = os.path.basename(f)
    volts = {}
    for i in range(1, 30):
        pn = meta.get(f"$P{i}N")
        pv = meta.get(f"$P{i}V")
        if pn and pv:
            volts[pn] = pv
    print(f"{name:25s} YG780-A: {volts.get('YG780-A')} FSC-A: {volts.get('FSC-A')} SSC-A: {volts.get('SSC-A')}")

EOF
python3 inspect_fcs.py
